@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Libre+Baskerville:wght@400;700&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#131916;--ink2:#1d2520;--paper:#e9e5d7;--muted:#9a9d8e;--olive:#a8ad76;--gold:#c8a86c;--rust:#a65d47;--line:rgba(225,224,205,.14);--mono:'DM Mono',monospace;--serif:'Libre Baskerville',Georgia,serif;--sans:'Manrope',Arial,sans-serif}*{box-sizing:border-box}html,body{height:100%;margin:0}body{background:#101512;color:var(--paper);font-family:var(--sans);overflow:hidden}.grain{position:fixed;inset:0;pointer-events:none;z-index:10;opacity:.13;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.3'/%3E%3C/svg%3E")}.app-shell{height:100%;position:relative;overflow:hidden}.topbar{position:absolute;z-index:5;left:0;right:0;top:0;height:68px;padding:0 4.4vw;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(220,221,202,.13);font:10px var(--mono);letter-spacing:.13em;color:#c6c7b5}.brand-mark{display:flex;align-items:center;gap:12px}.brand-mark i{font-style:normal;color:var(--gold);padding:0 3px}.brand-star{font-size:20px;color:var(--gold)}.topbar-right{display:flex;align-items:center;gap:12px;color:#92988a;font-size:9px}.live-dot{height:6px;width:6px;border-radius:50%;background:#a6a972;box-shadow:0 0 10px #a6a972}.top-divider{height:14px;width:1px;background:#52584d;margin:0 6px}.screen{position:absolute;inset:0;display:none}.screen.active{display:block}.menu-screen{background:#111713;overflow:hidden}.menu-visual{position:absolute;inset:68px 0 0 34%;background:radial-gradient(ellipse at 50% 45%,#353b2e 0%,#202720 44%,#151c18 100%);overflow:hidden}.map-wash{position:absolute;inset:0;background:linear-gradient(100deg,#151b17 0%,rgba(21,27,23,.32) 28%,rgba(21,27,23,.04) 60%,rgba(21,27,23,.32) 100%),linear-gradient(0deg,rgba(17,23,19,.55),transparent 40%,rgba(17,23,19,.18)}.map-grid{position:absolute;inset:0;opacity:.12;background-image:linear-gradient(rgba(209,199,159,.23) 1px,transparent 1px),linear-gradient(90deg,rgba(209,199,159,.23) 1px,transparent 1px);background-size:45px 45px;mask-image:linear-gradient(90deg,transparent 0%,#000 26%,#000)}.hero-map{position:absolute;width:113%;height:100%;left:0;top:2%;opacity:.8;filter:drop-shadow(0 3px 4px rgba(0,0,0,.24))}.land-shape{fill:#62614a;fill-opacity:.32;stroke:#b4a779;stroke-opacity:.5;stroke-width:1.2}.river{fill:none;stroke:#abb1a0;stroke-width:4;stroke-opacity:.36}.frontline{fill:none;stroke:#bc694d;stroke-width:3;stroke-opacity:.95}.frontline-dash{fill:none;stroke:#e1c4a0;stroke-width:.8;stroke-dasharray:3 7;stroke-opacity:.9}.towns circle{fill:#d7cba7;stroke:#1d211a;stroke-width:3}.map-labels{font:11px var(--mono);letter-spacing:2px;fill:#d0c8a7;opacity:.75}.contours{fill:none;stroke:#b1a77b;stroke-width:1;stroke-opacity:.13}.hero-vignette{position:absolute;inset:0;background:linear-gradient(90deg,#111713 0%,rgba(17,23,19,.95) 3%,rgba(17,23,19,.15) 31%,transparent 68%),linear-gradient(0deg,#111713 0%,transparent 16%,transparent 88%,#111713 100%)}.map-coordinate{position:absolute;font:9px var(--mono);letter-spacing:.12em;color:#c5c0a3;opacity:.6;z-index:1}.map-coordinate span{color:var(--rust);padding:0 4px}.coord-a{left:43%;top:18%}.coord-b{right:7%;bottom:8%}.menu-content{position:absolute;z-index:2;left:8.3%;top:15.5%;bottom:5%;width:405px;display:flex;flex-direction:column}.eyebrow{display:flex;align-items:center;gap:12px;color:var(--olive);font:9px var(--mono);letter-spacing:.2em}.eyebrow-line{height:1px;width:32px;background:var(--gold)}h1{font:700 clamp(58px,6.2vw,86px)/.94 var(--serif);letter-spacing:-.08em;margin:28px 0 11px;color:#ece9d9;text-shadow:0 3px 20px #111}.amp{color:#b4ad7e;font-style:italic;font-size:.88em}.subtitle{font:10px var(--mono);letter-spacing:.32em;color:#b9bca6;margin:0 0 16px}.title-rule{display:flex;align-items:center;gap:10px;width:224px;color:#a8a675;font-size:11px}.title-rule span{height:1px;background:linear-gradient(90deg,#8e885f,transparent);flex:1}.title-rule span:last-child{background:linear-gradient(90deg,transparent,#8e885f)}.intro{font:14px/1.8 var(--serif);font-style:italic;color:#c9c7b6;margin:14px 0 20px}.main-menu{width:100%;border-top:1px solid var(--line)}.menu-button{border:0;border-bottom:1px solid var(--line);background:transparent;color:inherit;width:100%;height:48px;display:grid;grid-template-columns:31px 1fr auto 20px;align-items:center;text-align:left;padding:0 8px 0 0;cursor:pointer;position:relative;transition:background .22s,padding .22s,color .22s}.menu-button:hover{background:linear-gradient(90deg,rgba(166,165,112,.11),transparent);padding-left:9px}.menu-button:focus-visible{outline:1px solid var(--gold);outline-offset:-2px}.menu-index{font:9px var(--mono);color:#747b6b}.menu-label{font-size:12px;letter-spacing:.02em;color:#e4e3d4}.menu-detail{font:8px var(--mono);letter-spacing:.08em;color:#858b7c;margin-right:13px}.menu-arrow{font-size:15px;color:#9e9d74;opacity:0;transform:translate(-3px,3px);transition:.2s}.menu-button:hover .menu-arrow{opacity:1;transform:translate(0)}.menu-button.primary .menu-label{color:#ececda;font-weight:700}.menu-button.primary .menu-index{color:var(--gold)}.menu-button.primary:before{content:'';position:absolute;left:-9px;top:0;bottom:0;width:2px;background:var(--gold)}.menu-button.locked{cursor:not-allowed;opacity:.48}.menu-button.locked:hover{background:none;padding-left:0}.lock-icon{color:#8e907e;font-size:12px}.exit-button{margin-top:7px}.menu-footer{display:flex;justify-content:space-between;align-items:center;margin-top:auto;padding-top:14px;color:#747b70;font:8px var(--mono);letter-spacing:.08em}.menu-footer b{color:#a5a58b;font-weight:400}.dispatch-card{position:absolute;z-index:2;right:6.4%;bottom:12%;width:235px;transform:rotate(2deg);padding:18px 20px 13px;background:rgba(219,210,177,.88);color:#302f25;box-shadow:0 12px 30px #0e120f88;border:1px solid #d5cca9}.dispatch-card:before{content:'';position:absolute;inset:5px;border:1px solid rgba(61,56,40,.22);pointer-events:none}.dispatch-top,.dispatch-bottom{display:flex;justify-content:space-between;align-items:center;font:8px var(--mono);letter-spacing:.12em}.dispatch-top{padding:0 2px 8px;border-bottom:1px solid #888265}.dispatch-stamp{border:1px solid #9c5540;color:#9c5540;padding:3px 5px;transform:rotate(-5deg);font-size:7px}.dispatch-card p{font:13px/1.8 var(--serif);font-style:italic;margin:12px 0 6px}.dispatch-sign{font:7px var(--mono);letter-spacing:.1em;color:#68634b;padding-bottom:13px}.dispatch-bottom{border-top:1px solid #9d9573;padding-top:8px;color:#706b53;font-size:7px}.menu-side-note{position:absolute;right:3.2%;top:46%;writing-mode:vertical-rl;font:8px var(--mono);letter-spacing:.2em;color:#bcb69a;opacity:.55}.menu-side-note span{color:#b46d54;padding:8px 0}
/* Campaign screen */
.game-screen{background:#141a16;grid-template-rows:68px 1fr;grid-template-columns:1fr;overflow:hidden}.game-screen.active{display:grid}.game-top{height:68px;grid-row:1;display:flex;justify-content:space-between;align-items:center;padding:0 30px;border-bottom:1px solid var(--line);background:#121814;z-index:2}.game-brand{display:flex;align-items:center;gap:14px}.back-button,.small-button{background:none;color:#b3b6a4;border:1px solid var(--line);padding:8px 12px;font:9px var(--mono);letter-spacing:.1em;cursor:pointer}.back-button:hover,.small-button:hover{border-color:var(--gold);color:var(--paper)}.game-title{font:700 14px var(--serif);letter-spacing:.08em}.game-title small{display:block;color:#888e7e;font:8px var(--mono);letter-spacing:.15em;margin-top:5px}.turn-display{font:10px var(--mono);letter-spacing:.13em;color:#c9c7b2}.turn-display strong{color:var(--gold);font-weight:500}.game-layout{grid-row:2;display:grid;grid-template-columns:minmax(0,1fr) 330px;min-height:0}.map-panel{position:relative;overflow:hidden;background:radial-gradient(ellipse at 48% 47%,#32382c,#1c241e 66%,#151c17)}.campaign-map{position:absolute;width:100%;height:100%;inset:0}.campaign-map .map-land{fill:#817e5d;fill-opacity:.23;stroke:#b6ad87;stroke-opacity:.45;stroke-width:1.5}.campaign-map .map-gridlines{stroke:#d4cda9;stroke-opacity:.11;stroke-width:.7}.campaign-map .map-river{fill:none;stroke:#8d9c91;stroke-width:4;stroke-opacity:.46}.campaign-map .frontline-path{fill:none;stroke:#b65d43;stroke-width:3;stroke-dasharray:10 6}.campaign-map .province{fill:#a79c70;fill-opacity:.1;stroke:#c7ba8a;stroke-opacity:.48;stroke-width:1.2;cursor:pointer;transition:.2s}.campaign-map .province:hover,.campaign-map .province.selected{fill:#d0b672;fill-opacity:.34;stroke:#e1c783;stroke-opacity:.9}.campaign-map .province.enemy{fill:#9d5944;fill-opacity:.17;stroke:#bc7659;stroke-opacity:.55}.campaign-map .place{fill:#ddd2ac;stroke:#21271f;stroke-width:3}.campaign-map .place-label{font:11px var(--mono);letter-spacing:1.5px;fill:#dfd7bc}.campaign-map .province-label{font:8px var(--mono);letter-spacing:1px;fill:#c5c0a9;opacity:.75}.campaign-map .unit-icon{cursor:pointer;transition:transform .2s}.campaign-map .unit-icon:hover{filter:drop-shadow(0 0 6px #ead28b)}.map-controls{position:absolute;top:18px;left:22px;display:flex;gap:8px;z-index:1}.map-tag,.map-legend{background:rgba(18,24,20,.78);border:1px solid rgba(225,224,205,.17);padding:9px 12px;color:#b5b69f;font:8px var(--mono);letter-spacing:.1em;backdrop-filter:blur(8px)}.map-legend{position:absolute;left:22px;bottom:22px;display:flex;gap:14px;align-items:center}.legend-item{display:flex;align-items:center;gap:6px}.legend-dot{width:7px;height:7px;border-radius:50%;background:#d4c694}.legend-dot.enemy{background:#ae664f}.legend-line{height:2px;width:18px;background:#b65d43}.map-compass{position:absolute;right:25px;top:20px;color:#d4cba9;text-align:center;font:10px var(--mono);opacity:.7}.map-compass b{display:block;font:22px var(--serif);font-weight:400}.command-panel{background:#191f1a;border-left:1px solid var(--line);padding:25px 24px;display:flex;flex-direction:column;overflow:auto}.panel-eyebrow{font:8px var(--mono);letter-spacing:.17em;color:#a2a27b}.commander-name{font:22px var(--serif);margin:9px 0 3px}.commander-role{font:9px var(--mono);letter-spacing:.12em;color:#939889}.stats-row{display:grid;grid-template-columns:repeat(3,1fr);margin:19px 0 21px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:12px 0}.stat small{display:block;color:#828979;font:8px var(--mono);letter-spacing:.08em;margin-bottom:6px}.stat strong{font:16px var(--serif);font-weight:400;color:#d3d0b8}.panel-heading{font:9px var(--mono);letter-spacing:.16em;color:#aeae88;padding-bottom:10px;border-bottom:1px solid var(--line);margin-bottom:10px}.order-list{display:flex;flex-direction:column;gap:7px}.order-card{border:1px solid rgba(225,224,205,.1);padding:11px 12px;background:#1d251f;display:flex;justify-content:space-between;align-items:center}.order-card strong{font-size:10px;font-weight:600}.order-card small{display:block;margin-top:4px;color:#888f7e;font:8px var(--mono)}.order-card span{font:8px var(--mono);color:#bba96d}.selected-box{margin-top:17px;padding:13px;background:#222b23;border-left:2px solid var(--gold);min-height:95px}.selected-box h3{margin:0 0 6px;font:13px var(--serif);font-weight:400}.selected-box p{margin:0;color:#a4a794;font:9px/1.6 var(--mono)}.order-actions{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:10px}.action-button{background:#283128;border:1px solid rgba(222,218,191,.16);color:#d8d6c3;padding:10px 6px;cursor:pointer;font:8px var(--mono);letter-spacing:.06em;transition:.2s}.action-button:hover:not(:disabled){background:#394435;border-color:#aaa575}.action-button:disabled{opacity:.35;cursor:not-allowed}.resolve-button{margin-top:12px;width:100%;background:#a39f70;border:0;color:#171c16;padding:13px;cursor:pointer;font:10px var(--mono);letter-spacing:.1em;font-weight:500;transition:.2s}.resolve-button:hover{background:#c1b982}.resolve-button:disabled{opacity:.4;cursor:not-allowed}.log-wrap{margin-top:auto;padding-top:20px}.event-log{height:96px;overflow:auto;color:#9da18f;font:8px/1.8 var(--mono);padding-right:5px}.event-log div{border-bottom:1px solid rgba(220,220,200,.06);padding:3px 0}.event-log em{color:#c1af77;font-style:normal}
/* dialog / intro */
#modal-root:empty{display:none}.modal-backdrop{position:absolute;z-index:8;inset:0;background:rgba(6,9,7,.76);backdrop-filter:blur(5px);display:grid;place-items:center;padding:20px;animation:fadein .18s ease}.modal{width:min(560px,96vw);background:#1b231d;border:1px solid rgba(213,204,165,.36);box-shadow:0 25px 80px #0009;position:relative;padding:34px 38px 31px}.modal:before{content:'';position:absolute;inset:7px;border:1px solid rgba(213,204,165,.1);pointer-events:none}.modal-close{position:absolute;right:22px;top:20px;border:0;background:none;color:#aaa993;font-size:20px;cursor:pointer}.modal-kicker{font:8px var(--mono);letter-spacing:.17em;color:#b2aa76}.modal h2{font:24px var(--serif);font-weight:400;margin:13px 0 15px}.modal-copy{color:#b2b4a2;font:12px/1.8 var(--sans);max-width:470px}.modal-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:24px}.modal-primary,.modal-secondary{padding:11px 17px;border:1px solid #a6a276;background:#a6a276;color:#161b16;cursor:pointer;font:9px var(--mono);letter-spacing:.1em}.modal-secondary{background:transparent;color:#c1c0ac;border-color:rgba(225,224,205,.2)}.modal-primary:hover{background:#c3bd8e}.option-row{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding:13px 0;color:#d2d0bd;font-size:11px}.option-row small{display:block;color:#828979;font:8px var(--mono);margin-top:5px}.toggle{width:38px;height:20px;border:1px solid #777c69;background:#313830;border-radius:12px;position:relative;cursor:pointer}.toggle:after{content:'';position:absolute;left:3px;top:3px;width:12px;height:12px;border-radius:50%;background:#919583;transition:.2s}.toggle.on{background:#8e9066;border-color:#b4b17f}.toggle.on:after{left:20px;background:#f0ecd8}.difficulty{background:#273027;border:1px solid #53604d;color:#dedbc5;padding:7px 10px;font:9px var(--mono)}.intro-modal{width:min(700px,96vw)}.briefing-grid{display:grid;grid-template-columns:1fr 180px;gap:24px;margin-top:20px}.briefing-grid p{margin:0;color:#bdbead;font:12px/1.9 var(--serif)}.briefing-aside{border-left:1px solid var(--line);padding-left:17px;font:8px/2 var(--mono);letter-spacing:.06em;color:#999d88}.briefing-aside b{color:#c6b77f;font-weight:400}.modal-rule{height:1px;background:linear-gradient(90deg,#a49b70,transparent);margin:18px 0}.save-info{font:9px/1.8 var(--mono);color:#969b88}.toast{position:absolute;z-index:9;bottom:24px;left:50%;transform:translateX(-50%);background:#e2dcc2;color:#20251e;padding:11px 17px;font:9px var(--mono);letter-spacing:.06em;box-shadow:0 6px 25px #0007;animation:toastin .2s ease}.menu-screen.dispatched .menu-content{animation:menuout .4s ease forwards}.exit-screen{position:absolute;inset:68px 0 0;background:#111713;z-index:6;display:grid;place-items:center;text-align:center}.exit-screen h2{font:28px var(--serif);font-weight:400}.exit-screen p{font:10px var(--mono);color:#929788;letter-spacing:.12em}.exit-screen button{margin-top:20px}@keyframes fadein{from{opacity:0}to{opacity:1}}@keyframes toastin{from{opacity:0;transform:translate(-50%,10px)}to{opacity:1;transform:translate(-50%,0)}}@keyframes menuout{to{opacity:0;transform:translateX(-15px)}}
@media(max-width:900px){.menu-content{left:6%;width:370px}.dispatch-card{right:4%;bottom:8%;transform:scale(.88) rotate(2deg);transform-origin:bottom right}.game-layout{grid-template-columns:minmax(0,1fr) 300px}.menu-detail{font-size:7px}.menu-side-note{display:none}}
@media(max-width:680px){body{overflow:auto}.app-shell{min-height:100%;height:100dvh}.topbar{height:56px;padding:0 18px}.topbar-right{font-size:8px;gap:7px}.menu-visual{inset:56px 0 0 0;opacity:.56}.hero-map{width:150%;left:-24%;height:90%;top:5%}.hero-vignette{background:linear-gradient(90deg,rgba(17,23,19,.8),rgba(17,23,19,.35)),linear-gradient(0deg,#111713,transparent 45%,#111713)}.menu-content{left:8%;top:10%;bottom:4%;width:84%}h1{font-size:62px;margin-top:21px}.intro{margin:10px 0 12px;font-size:12px}.menu-button{height:44px;grid-template-columns:28px 1fr auto 18px}.menu-label{font-size:11px}.dispatch-card{display:none}.menu-footer{font-size:7px}.menu-footer span:last-child{display:none}.coord-a{left:62%;top:10%}.coord-b{right:4%;bottom:4%}.game-screen.active{grid-template-rows:56px 1fr}.game-top{height:56px;padding:0 12px}.game-title{font-size:12px}.game-title small{font-size:7px}.back-button{padding:7px;font-size:8px}.turn-display{font-size:8px}.game-layout{grid-template-columns:1fr;grid-template-rows:minmax(240px,45vh) auto;overflow:auto}.map-panel{min-height:240px}.command-panel{border-left:0;border-top:1px solid var(--line);padding:18px 17px}.stats-row{margin:12px 0 15px;padding:10px 0}.log-wrap{margin-top:18px}.event-log{height:70px}.map-legend{left:10px;bottom:10px;padding:7px;font-size:7px;gap:8px}.map-controls{left:10px;top:10px}.map-tag{padding:7px;font-size:7px}.map-compass{right:12px;top:12px}.briefing-grid{grid-template-columns:1fr}.briefing-aside{border-left:0;border-top:1px solid var(--line);padding:12px 0 0}.modal{padding:30px 24px 24px}.modal h2{font-size:21px}.modal-copy,.briefing-grid p{font-size:11px}}

(()=>{
  const $=s=>document.querySelector(s), root=$('#modal-root'), menu=$('#menu-screen'), game=$('#game-screen');
  const SAVE_KEY='iron-ash-campaign-v1', PREF_KEY='iron-ash-options-v1';
  let prefs=JSON.parse(localStorage.getItem(PREF_KEY)||'{"animations":true,"difficulty":"Standard"}');
  let state=null, selectedUnit=null, selectedNode='verdun', toastTimer;
  const nodes={
    verdun:{name:'Verdun',x:210,y:355,owner:'allied',neighbors:['montfaucon','st-mihiel'],description:'A battered fortress city. The line holds—for now.'},
    'st-mihiel':{name:'St. Mihiel',x:360,y:525,owner:'allied',neighbors:['verdun','varennes'],description:'A vital road junction anchoring the southern flank.'},
    montfaucon:{name:'Montfaucon',x:470,y:300,owner:'neutral',neighbors:['verdun','varennes','metz'],description:'High ground overlooking the old front.'},
    varennes:{name:'Varennes',x:630,y:455,owner:'enemy',neighbors:['montfaucon','st-mihiel','metz'],description:'A crossroads held by the enemy garrison.'},
    metz:{name:'Metz Road',x:820,y:290,owner:'enemy',neighbors:['montfaucon','varennes'],description:'The supply road east. Capture it to open the advance.'}
  };
  const initialState=()=>({turn:1,month:9,year:1916,day:18,supply:72,morale:68,reinforcements:1,won:false,lost:false,log:['<em>18 SEP 1916</em> — You assume command of the 4th Field Brigade.','<em>ORDERS</em> — Secure the crossings at Varennes and the Metz Road.'],units:[{id:'4th',name:'4th Infantry',rank:'Veteran regiment',node:'verdun',strength:76,morale:72,orders:0},{id:'12th',name:'12th Rifles',rank:'Line infantry',node:'st-mihiel',strength:64,morale:65,orders:0}],pending:[]});
  function safeSave(){if(!state)return;localStorage.setItem(SAVE_KEY,JSON.stringify(state));updateSaveLabel()}
  function updateSaveLabel(){const saved=localStorage.getItem(SAVE_KEY);$('#save-status').textContent=saved?'FIELD RECORD · TURN '+(JSON.parse(saved).turn):'NO FIELD RECORD FOUND'}
  function notify(message){let old=$('.toast');if(old)old.remove();const el=document.createElement('div');el.className='toast';el.textContent=message;document.body.appendChild(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),2300)}
  function closeModal(){root.innerHTML=''}
  function showModal(content, extra='') {root.innerHTML=`<div class="modal-backdrop"><div class="modal ${extra}" role="dialog" aria-modal="true">${content}</div></div>`;root.querySelector('.modal-close')?.addEventListener('click',closeModal);root.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()})}
  function showBiography(){showModal(`<button class="modal-close" aria-label="Close">×</button><div class="modal-kicker">A HISTORY OF THE WESTERN FRONT</div><h2>The war behind the map</h2><div class="modal-rule"></div><p class="modal-copy">Europe has been at war since the summer of 1914. By 1916, the Western Front has hardened into a vast scar of trenches, wire, and artillery. At Verdun, France has sworn <em>“They shall not pass.”</em> In the north, the Somme offensive grinds forward at terrible cost.</p><p class="modal-copy">You are a newly appointed field officer in the 4th Brigade, assigned to a quiet but crucial sector of the Meuse-Argonne. Your orders are simple: keep your men alive, hold the crossings, and be ready when history turns its face toward you.</p><div class="briefing-grid"><p>There are no grand speeches in the trenches. There is only the next dispatch, the next dawn, and the people who trust you to bring them home.</p><aside><b>THEATRE</b><br>Western Front<br><b>COMMAND</b><br>4th Field Brigade<br><b>DATE</b><br>September 1916</aside></div><div class="modal-actions"><button class="modal-primary" data-close>RETURN TO MENU</button></div>`,'intro-modal');root.querySelector('[data-close]').onclick=closeModal}
  function showOptions(){showModal(`<button class="modal-close" aria-label="Close">×</button><div class="modal-kicker">FIELD OFFICE / PREFERENCES</div><h2>Options</h2><div class="option-row"><div>Interface motion<small>Subtle transitions and map effects</small></div><button class="toggle ${prefs.animations?'on':''}" data-option="animations" aria-label="Toggle animations"></button></div><div class="option-row"><div>Campaign difficulty<small>Adjusts enemy pressure and combat odds</small></div><select class="difficulty" id="difficulty"><option ${prefs.difficulty==='Relaxed'?'selected':''}>Relaxed</option><option ${prefs.difficulty==='Standard'?'selected':''}>Standard</option><option ${prefs.difficulty==='Hard'?'selected':''}>Hard</option></select></div><div class="modal-actions"><button class="modal-primary" data-close>SAVE PREFERENCES</button></div>`);root.querySelector('[data-option]').onclick=()=>{prefs.animations=!prefs.animations;root.querySelector('.toggle').classList.toggle('on',prefs.animations)};root.querySelector('[data-close]').onclick=()=>{prefs.difficulty=$('#difficulty').value;localStorage.setItem(PREF_KEY,JSON.stringify(prefs));document.body.classList.toggle('no-motion',!prefs.animations);closeModal();notify('Preferences saved')}}
  function beginNew(){state=initialState();selectedUnit=null;selectedNode='verdun';menu.classList.remove('dispatched');renderGame();menu.classList.remove('active');game.classList.add('active');safeSave()}
  function loadGame(){const data=localStorage.getItem(SAVE_KEY);if(!data){notify('No saved campaign found. Begin a new campaign first.');return}try{state=JSON.parse(data);selectedUnit=null;selectedNode='verdun';menu.classList.remove('active');game.classList.add('active');renderGame()}catch(e){notify('The field record could not be read.')}}
  function campaignMap(){let edges='';Object.entries(nodes).forEach(([id,n])=>n.neighbors.forEach(other=>{if(id<other){const p=nodes[other];edges+=`<line class="map-gridlines" x1="${n.x}" y1="${n.y}" x2="${p.x}" y2="${p.y}"/>`}}));let places=Object.entries(nodes).map(([id,n])=>`<g class="node-hit" data-node="${id}"><circle class="province ${n.owner==='enemy'?'enemy':''} ${selectedNode===id?'selected':''}" cx="${n.x}" cy="${n.y}" r="52"/><circle class="place" cx="${n.x}" cy="${n.y}" r="5"/><text class="place-label" x="${n.x+13}" y="${n.y+4}">${n.name.toUpperCase()}</text><text class="province-label" x="${n.x-34}" y="${n.y+24}">${n.owner==='enemy'?'ENEMY POSITION':n.owner==='neutral'?'CONTESTED GROUND':'ALLIED SECTOR'}</text></g>`).join('');let units=state.units.map(u=>{const n=nodes[u.node];return `<g class="unit-icon" data-unit="${u.id}" transform="translate(${n.x-12},${n.y-30})"><path d="M0 0h24v17H0z" fill="${u.id==='12th'?'#9caa85':'#c6b779'}" stroke="#1c2119" stroke-width="2"/><text x="12" y="12" text-anchor="middle" font-family="DM Mono" font-size="8" fill="#182019">${u.id==='12th'?'12':'4'}</text></g>`}).join('');return `<svg class="campaign-map" viewBox="0 0 1000 760" preserveAspectRatio="xMidYMid meet" aria-label="Campaign map">${edges}<path class="map-land" d="M55 150 178 98l106 39 80-31 124 55 118-24 93 51 142-18 105 85-37 102 37 86-69 90-26 126-120 1-87 48-112-39-95 34-109-62-103 18-96-61-70-11-47-98 31-89-37-98z"/><path class="map-river" d="M100 600c98-16 120-166 222-137s101 102 195 45 124-100 216-53 117 89 222 35"/><path class="frontline-path" d="M314 218q108 24 156 82t136 20 103 42 129-41"/>${places}${units}</svg>`}
  function renderGame(){if(!state)return;const d=new Date(state.year,state.month-1,state.day);const date=d.toLocaleDateString('en-US',{day:'2-digit',month:'short',year:'numeric'}).toUpperCase();const unit=state.units.find(u=>u.id===selectedUnit);const target=nodes[selectedNode];const pending=state.pending||[];$('#top-date').textContent=date;game.innerHTML=`<header class="game-top"><div class="game-brand"><button class="back-button" data-back>← MENU</button><div class="game-title">THE MEUSE-ARGONNE<small>4TH FIELD BRIGADE / OPERATIONS ROOM</small></div></div><div class="turn-display">TURN <strong>${String(state.turn).padStart(2,'0')}</strong> &nbsp;·&nbsp; ${date}</div><button class="small-button" data-save>SAVE</button></header><div class="game-layout"><div class="map-panel"><div class="map-controls"><div class="map-tag">SECTOR 04 &nbsp; / &nbsp; 1:250,000</div><div class="map-tag">${state.units.length} REGIMENTS IN THE FIELD</div></div>${campaignMap()}<div class="map-compass"><b>↑</b>N</div><div class="map-legend"><span class="legend-item"><i class="legend-dot"></i> FRIENDLY</span><span class="legend-item"><i class="legend-dot enemy"></i> ENEMY</span><span class="legend-item"><i class="legend-line"></i> FRONT LINE</span></div></div><aside class="command-panel"><div class="panel-eyebrow">COMMANDING OFFICER</div><div class="commander-name">Lt. A. Mercer</div><div class="commander-role">4TH FIELD BRIGADE &nbsp;·&nbsp; MEUSE SECTOR</div><div class="stats-row"><div class="stat"><small>SUPPLIES</small><strong>${state.supply}%</strong></div><div class="stat"><small>MORALE</small><strong>${state.morale}%</strong></div><div class="stat"><small>TURN</small><strong>${String(state.turn).padStart(2,'0')}</strong></div></div><div class="panel-heading">AVAILABLE UNITS / SELECT TO COMMAND</div><div class="order-list">${state.units.map(u=>`<div class="order-card unit-select" data-select-unit="${u.id}" style="cursor:pointer;border-color:${selectedUnit===u.id?'#a6a276':'rgba(225,224,205,.1)'}"><div><strong>${u.name}</strong><small>${u.rank} · ${nodes[u.node].name}</small></div><span>${u.strength}%</span></div>`).join('')}</div>${state.reinforcements?`<button class="action-button" data-recruit style="width:100%;margin-top:8px">＋ &nbsp; REQUEST REINFORCEMENTS <small>1 AVAILABLE · COST 15 SUPPLY</small></button>`:''}<div class="selected-box"><h3>${unit?unit.name+' · '+target.name:target.name}</h3><p>${unit?`${unit.strength}% strength · ${unit.morale}% morale · ${unit.orders?'ORDER ASSIGNED':'AWAITING ORDERS'}<br>${target.description}`:`${target.description}<br>Select a unit, then choose its order.`}</p></div><div class="order-actions"><button class="action-button" data-order="advance" ${!unit||unit.orders||!target||!nodes[unit.node].neighbors.includes(selectedNode)||state.supply<8?'disabled':''}>↗ &nbsp; ADVANCE</button><button class="action-button" data-order="entrench" ${!unit||unit.orders?'disabled':''}>⌂ &nbsp; ENTRENCH</button><button class="action-button" data-order="resupply" ${!unit||unit.orders||state.supply<10?'disabled':''}>＋ &nbsp; RESUPPLY</button><button class="action-button" data-order="hold" ${!unit||unit.orders?'disabled':''}>◈ &nbsp; HOLD POSITION</button></div><button class="resolve-button" data-resolve ${!pending.length?'disabled':''}>${pending.length?'RESOLVE ORDERS · '+pending.length+' QUEUED':'ISSUE ORDERS TO PROCEED'}</button><div class="log-wrap"><div class="panel-heading">FIELD DISPATCHES</div><div class="event-log">${state.log.slice(-5).reverse().map(line=>`<div>${line}</div>`).join('')}</div></div></aside></div>${state.won||state.lost?`<div class="modal-backdrop"><div class="modal"><div class="modal-kicker">${state.won?'OBJECTIVE SECURED':'BRIGADE STATUS'}</div><h2>${state.won?'The line moves east.':'A costly retreat.'}</h2><p class="modal-copy">${state.won?'Your brigade has taken both Varennes and the Metz Road. The dispatch is sent; your men will be remembered.':'The brigade can no longer hold the sector. The war continues, but your command is relieved.'}</p><div class="modal-actions"><button class="modal-primary" data-return>RETURN TO MENU</button><button class="modal-secondary" data-continue>CONTINUE CAMPAIGN</button></div></div></div>`:''}`;
    game.querySelector('[data-back]').onclick=()=>{safeSave();game.classList.remove('active');menu.classList.add('active');updateSaveLabel()};game.querySelector('[data-save]').onclick=()=>{safeSave();notify('Campaign saved to the field record.')};game.querySelectorAll('[data-select-unit]').forEach(el=>el.onclick=()=>{selectedUnit=el.dataset.selectUnit;renderGame()});game.querySelectorAll('[data-node]').forEach(el=>el.onclick=e=>{if(e.target.closest('[data-unit]'))return;selectedNode=el.dataset.node;renderGame()});game.querySelectorAll('[data-unit]').forEach(el=>el.onclick=e=>{e.stopPropagation();selectedUnit=el.dataset.unit;selectedNode=state.units.find(u=>u.id===selectedUnit).node;renderGame()});game.querySelectorAll('[data-order]').forEach(el=>el.onclick=()=>queueOrder(el.dataset.order));game.querySelector('[data-resolve]')?.addEventListener('click',resolveOrders);game.querySelector('[data-recruit]')?.addEventListener('click',recruit);game.querySelector('[data-return]')?.addEventListener('click',()=>{state=null;game.classList.remove('active');menu.classList.add('active');updateSaveLabel()});game.querySelector('[data-continue]')?.addEventListener('click',()=>renderGame())
  }
  function log(text){state.log.push(`<em>${String(state.day).padStart(2,'0')} ${new Date(state.year,state.month-1).toLocaleString('en-US',{month:'short'}).toUpperCase()} ${state.year}</em> — ${text}`);if(state.log.length>20)state.log.shift()}
  function queueOrder(type){const u=state.units.find(x=>x.id===selectedUnit);if(!u||u.orders)return;if(type==='advance'&&(!nodes[u.node].neighbors.includes(selectedNode)||state.supply<8))return;if(type==='resupply'&&state.supply<10)return;const dest=type==='advance'?selectedNode:u.node;state.pending.push({unit:u.id,type,dest});u.orders=1;renderGame();notify('Order queued. Resolve orders to carry it out.')}
  function resolveOrders(){if(!state.pending.length)return;for(const order of state.pending){const u=state.units.find(x=>x.id===order.unit);if(!u)continue;if(order.type==='advance'){state.supply=Math.max(0,state.supply-8);const node=nodes[order.dest];if(node.owner==='enemy'){const base=prefs.difficulty==='Relaxed'?78:prefs.difficulty==='Hard'?46:62;const chance=base+(u.strength-60)*.35+(state.morale-60)*.2+(node.owner==='neutral'?10:0);if(Math.random()*100<chance){u.node=order.dest;node.owner='allied';u.strength=Math.max(22,u.strength-(prefs.difficulty==='Hard'?25:17));u.morale=Math.max(20,u.morale-10);log(`${u.name} captured ${node.name} after a sharp engagement.`)}else{u.strength=Math.max(18,u.strength-22);u.morale=Math.max(15,u.morale-14);state.morale=Math.max(10,state.morale-5);log(`${u.name} was repulsed near ${node.name}; casualties were heavy.`)}}else{u.node=order.dest;if(node.owner==='neutral')node.owner='allied';u.strength=Math.max(20,u.strength-4);log(`${u.name} advanced to ${node.name} and secured the ground.`)}}else if(order.type==='entrench'){u.morale=Math.min(100,u.morale+8);u.strength=Math.min(100,u.strength+4);log(`${u.name} dug in and strengthened its position.`)}else if(order.type==='resupply'){state.supply=Math.max(0,state.supply-10);u.strength=Math.min(100,u.strength+19);u.morale=Math.min(100,u.morale+4);log(`${u.name} received ammunition and field rations.`)}else{u.morale=Math.min(100,u.morale+3);log(`${u.name} is holding its position.`)}u.orders=0}state.pending=[];state.turn++;state.day+=7;if(state.day>28){state.day=4;state.month++}if(state.month>12){state.month=1;state.year++}const enemyPressure=prefs.difficulty==='Relaxed'?3:prefs.difficulty==='Hard'?10:6;state.supply=Math.max(0,state.supply-enemyPressure);if(Math.random()<.45){state.morale=Math.max(10,state.morale-2);log('Enemy shelling has shaken the sector. Brigade morale falls.')}else log('A quiet week on the line. The brigade consolidates.');if(state.supply===0){state.morale=Math.max(0,state.morale-8);log('Supply lines are cut. Morale is collapsing.')}state.won=nodes.varennes.owner==='allied'&&nodes.metz.owner==='allied';state.lost=state.morale<=8||state.turn>12&&!state.won;selectedUnit=null;selectedNode='verdun';safeSave();renderGame()}
  function recruit(){if(!state.reinforcements||state.supply<15)return;state.reinforcements--;state.supply-=15;state.units.push({id:'8th',name:'8th Reserve',rank:'Fresh reinforcements',node:'verdun',strength:55,morale:70,orders:0});log('The 8th Reserve has arrived at Verdun.');selectedUnit='8th';renderGame();safeSave()}
  document.querySelectorAll('.menu-button').forEach(button=>button.addEventListener('click',()=>{const action=button.dataset.action;if(action==='new'){showModal(`<button class="modal-close" aria-label="Close">×</button><div class="modal-kicker">NEW CAMPAIGN / 18 SEPTEMBER 1916</div><h2>Assume command?</h2><p class="modal-copy">You have been assigned to the Meuse-Argonne sector. Two regiments are under your command. Your objective: secure Varennes and the Metz Road, and keep the brigade together.</p><div class="briefing-grid"><p>The front is unstable. Every order costs supplies. Advance into enemy-held ground at your own risk; entrench to recover morale, or request the reserve before it is too late.</p><aside><b>STARTING FORCE</b><br>2 Regiments<br><b>OBJECTIVE</b><br>Capture 2 positions<br><b>DIFFICULTY</b><br>${prefs.difficulty}</aside></div><div class="modal-actions"><button class="modal-secondary" data-cancel>STAND DOWN</button><button class="modal-primary" data-start>TAKE COMMAND</button></div>`,'intro-modal');root.querySelector('[data-cancel]').onclick=closeModal;root.querySelector('[data-start]').onclick=()=>{closeModal();beginNew()}}else if(action==='load')loadGame();else if(action==='options')showOptions();else if(action==='bio')showBiography();else if(action==='character')notify('Character creation is locked in this edition.');else if(action==='exit'){menu.innerHTML+=`<div class="exit-screen"><div><div class="modal-kicker">FIELD OFFICE / SERVICE ENDED</div><h2>The record will remember.</h2><p>Your campaign has been safely kept.</p><button class="modal-primary" data-return-menu>RETURN TO THE FIELD OFFICE</button></div></div>`;menu.querySelector('[data-return-menu]').onclick=()=>menu.querySelector('.exit-screen')?.remove()}}));
  updateSaveLabel();document.body.classList.toggle('no-motion',!prefs.animations);
})();

