19:   function showBiography(){showModal(`<button class="modal-close" aria-label="Close">×</button><div class="modal-kicker">A HISTORY OF THE WESTERN FRONT</div><h2>The war behind the map</h2><div class="modal-rule"></div><p class="modal-copy">Europe has been at war since the summer of 1914. By 1916, the Western Front has hardened into a vast scar of trenches, wire, and artillery. At Verdun, France has sworn <em>“They shall not pass.”</em> In the north, the Somme offensive grinds forward at terrible cost.</p><p class="modal-copy">You are a newly appointed field officer in the 4th Brigade, assigned to a quiet but crucial sector of the Meuse-Argonne. Your orders are simple: keep your men alive, hold the crossings, and be ready when history turns its face toward you.</p><div class="briefing-grid"><p>There are no grand speeches in the trenches. There is only the next dispatch, the next dawn, and the people who trust you to bring them home.</p><aside><b>THEATRE</b><br>Western Front<br><b>COMMAND</b><br>4th Field Brigade<br><b>DATE</b><br>September 1916</aside></div><div class="modal-actions"><button class="modal-primary" data-close>RETURN TO MENU</button></div>`,'intro-modal');root.querySelector('[data-close]').onclick=closeModal}
20:   function showOptions(){showModal(`<button class="modal-close" aria-label="Close">×</button><div class="modal-kicker">FIELD OFFICE / PREFERENCES</div><h2>Options</h2><div class="option-row"><div>Interface motion<small>Subtle transitions and map effects</small></div><button class="toggle ${prefs.animations?'on':''}" data-option="animations" aria-label="Toggle animations"></button></div><div class="option-row"><div>Campaign difficulty<small>Adjusts enemy pressure and combat odds</small></div><select class="difficulty" id="difficulty"><option ${prefs.difficulty==='Relaxed'?'selected':''}>Relaxed</option><option ${prefs.difficulty==='Standard'?'selected':''}>Standard</option><option ${prefs.difficulty==='Hard'?'selected':''}>Hard</option></select></div><div class="modal-actions"><button class="modal-primary" data-close>SAVE PREFERENCES</button></div>`);root.querySelector('[data-option]').onclick=()=>{prefs.animations=!prefs.animations;root.querySelector('.toggle').classList.toggle('on',prefs.animations)};root.querySelector('[data-close]').onclick=()=>{prefs.difficulty=$('#difficulty').value;localStorage.setItem(PREF_KEY,JSON.stringify(prefs));document.body.classList.toggle('no-motion',!prefs.animations);closeModal();notify('Preferences saved')}}
