python3 - <<'PY'
import re
s=open('styles.css').read()
for selector, body in re.findall(r'([^{}]+)\{([^{}]*)\}', s):
    props=[]
    for key,val in re.findall(r'([\w-]+):([^;]+)',body):
        if key in ('background','background-color','color','border','border-color','box-shadow'):
            if re.search(r'#[0-9a-fA-F]{3,8}|rgba?\(|var\(--',val): props.append(f'{key}:{val.strip()}')
    if props: print(selector.strip(), ' | '.join(props))
PY

