python3 - <<'PY'
try:
 import tinycss2
 for path in ('styles.css', 'light-theme.css'):
  css=open(path).read()
  errors=[node for node in tinycss2.parse_stylesheet(css, skip_whitespace=True, skip_comments=True) if node.type=='error']
  print(path, 'CSS parse errors:', len(errors))
  for error in errors: print(error)
except ImportError:
 print('tinycss2 unavailable; skipped CSS parser check')
PY

