input.content:
/* Fantasy parchment theme: enchanted vellum, old gold, and spellbound mapwork. */
:root {
  --ink: #fffaf0;
  --ink2: #fffdf7;
  --paper: #30253f;
  --muted: #796d80;
  --olive: #657f79;
  --gold: #a97932;
  --rust: #a45555;
  --line: rgba(68, 51, 79, .18);
  --serif: 'Cormorant Garamond', Georgia, serif;
}

body { background: #f6f0df; color: var(--paper); }
.grain { opacity: .055; mix-blend-mode: multiply; }
.topbar { color: #564762; border-color: rgba(68, 51, 79, .18); }
.topbar-right { color: #796d80; }
.top-divider { background: #d3c6ad; }
.live-dot { background: #718b72; box-shadow: 0 0 11px rgba(113, 139, 114, .55); }
.brand-mark i { color: var(--gold); }
.brand-star { color: #b3833d; text-shadow: 0 0 12px rgba(179, 131, 61, .38); }
.menu-screen, .exit-screen { background: #f6f0df; }
.menu-visual {
  background:
    radial-gradient(ellipse at 63% 40%, rgba(201, 188, 219, .74), transparent 43%),
    radial-gradient(ellipse at 77% 76%, rgba(167, 197, 184, .55), transparent 38%),
    radial-gradient(ellipse at 51% 47%, #e8dfcb 0%, #e4e6d9 48%, #f2ecdc 100%);
}
.menu-visual:after {
  content: '';
  position: absolute;
  inset: 9% 8%;
  pointer-events: none;
  opacity: .22;
  background: repeating-radial-gradient(ellipse at 62% 44%, transparent 0 42px, rgba(125, 99, 150, .4) 43px 44px, transparent 45px 82px);
  mask-image: radial-gradient(ellipse, #000 4%, transparent 72%);
}
.map-wash { background: linear-gradient(100deg, #f6f0df 0%, rgba(246,240,223,.88) 22%, rgba(246,240,223,.2) 67%, rgba(246,240,223,.48) 100%), linear-gradient(0deg, rgba(246,240,223,.55), transparent 40%, rgba(246,240,223,.22)); }
.hero-vignette { background: linear-gradient(90deg, #f6f0df 0%, rgba(246,240,223,.95) 3%, rgba(246,240,223,.18) 34%, transparent 68%), linear-gradient(0deg, #f6f0df 0%, transparent 16%, transparent 88%, #f6f0df 100%); }
.hero-map { filter: drop-shadow(0 0 14px rgba(116, 95, 140, .12)); }
.land-shape { fill: #b8b69f; stroke: #8d8874; }
.river { stroke: #7d9eaa; filter: drop-shadow(0 0 4px rgba(92, 151, 174, .45)); }
.frontline { stroke: #a45555; }
.frontline-dash { stroke: #f5d894; }
.map-labels { fill: #686079; opacity: .76; }
.contours { stroke: #958a9e; opacity: .6; }
.map-coordinate { color: #6d6277; }
.eyebrow, .panel-eyebrow { color: #687e74; }
.menu-brand h1, h1 { color: #30253f; text-shadow: 0 3px 22px rgba(255,255,255,.62); font-family: 'Cinzel', Georgia, serif; }
.amp { color: #a97932; }
.subtitle { color: #71647a; letter-spacing: .23em; }
.title-rule { color: #a97932; }
.intro { color: #62566d; }
.menu-index { color: #81748a; }
.menu-label, .menu-button.primary .menu-label { color: #352a44; }
.menu-detail { color: #796f7c; }
.menu-arrow { color: #a97932; }
.lock-icon { color: #8b8090; }
.menu-footer { color: #796f7c; }
.menu-footer b { color: #5a4c68; }
.menu-button { border-color: rgba(68, 51, 79, .2); }
.menu-button:hover { background: linear-gradient(90deg, rgba(101,127,121,.13), rgba(169,121,50,.04), transparent); }
.menu-button.primary:before { background: linear-gradient(180deg, #b88d4b, #8c6935); }
.menu-side-note { color: #796e80; }
.dispatch-card { background: rgba(255,252,242,.94); color: #382d45; border-color: #d7c8aa; box-shadow: 0 12px 32px rgba(62,48,70,.14); }
.dispatch-card:before { border-color: rgba(129,94,49,.24); }
.dispatch-stamp { color: #9c5952; }
.dispatch-sign, .dispatch-bottom { color: #756a77; }
.game-screen { background: #f2ecdc; }
.game-top { background: #fbf8ee; border-color: rgba(68,51,79,.16); }
.game-title { color: #352a44; font-family: 'Cinzel', Georgia, serif; }
.game-title small, .commander-role { color: #796f7c; }
.turn-display { color: #62566d; }
.turn-display strong { color: #a97932; }
.back-button, .small-button { color: #5b5065; border-color: rgba(68,51,79,.2); }
.back-button:hover, .small-button:hover { color: #30253f; border-color: var(--gold); }
.map-panel { background: radial-gradient(ellipse at 52% 43%, #e6e2d2, #dce5dc 66%, #ebe4d4); }
.campaign-map .map-land { fill: #aaa98e; fill-opacity: .38; stroke: #807c6d; stroke-opacity: .72; }
.campaign-map .map-gridlines { stroke: #827a8e; stroke-opacity: .2; }
.campaign-map .map-river { stroke: #6f9ca8; stroke-opacity: .78; filter: drop-shadow(0 0 3px rgba(77,146,164,.35)); }
.campaign-map .province { fill: #a89c70; fill-opacity: .1; stroke: #888064; stroke-opacity: .72; }
.campaign-map .province:hover, .campaign-map .province.selected { fill: #d7bd77; fill-opacity: .42; stroke: #a97932; stroke-opacity: .98; filter: drop-shadow(0 0 5px rgba(185,142,66,.3)); }
.campaign-map .province.enemy { fill: #ad6863; fill-opacity: .2; stroke: #a45555; stroke-opacity: .78; }
.campaign-map .place { fill: #fffaf0; stroke: #54465e; }
.campaign-map .place-label { fill: #3c3048; }
.campaign-map .province-label { fill: #625b68; }
.map-tag, .map-legend { background: rgba(255,252,242,.94); border-color: rgba(68,51,79,.2); color: #5b5065; }
.map-compass { color: #665871; }
.command-panel { background: #fbf8ee; }
.commander-name { color: #352a44; }
.stat small { color: #796f7c; }
.stat strong { color: #40344c; }
.panel-heading { color: #687e74; }
.order-card { background: #f3efe3; border-color: rgba(68,51,79,.16); }
.order-card small { color: #796f7c; }
.order-card span { color: #987139; }
.selected-box { background: #f0ecdf; }
.selected-box p { color: #62566d; }
.action-button { background: #f4f0e5; border-color: rgba(68,51,79,.2); color: #51465c; }
.action-button:hover:not(:disabled) { background: #e9e4d6; border-color: #a99a78; }
.resolve-button { background: #74887a; color: #fffaf0; }
.resolve-button:hover { background: #5f7467; }
.event-log { color: #6f6475; }
.event-log em { color: #987139; }
.modal-backdrop { background: rgba(48,37,63,.32); }
.modal { background: #fffdf7; border-color: rgba(169,121,50,.42); box-shadow: 0 25px 80px rgba(48,37,63,.22); }
.modal:before { border-color: rgba(169,121,50,.19); }
.modal-close { color: #71677a; }
.modal-kicker { color: #8d6a35; }
.modal h2 { color: #352a44; font-family: 'Cinzel', Georgia, serif; }
.modal-copy, .briefing-grid p { color: #5d5267; }
.modal-primary, .modal-secondary { border-color: #8e754e; background: #8e754e; color: #fffdf7; }
.modal-secondary { background: transparent; color: #5b5065; border-color: rgba(68,51,79,.23); }
.modal-primary:hover { background: #75603f; }
.option-row { color: #40344c; border-color: rgba(68,51,79,.16); }
.option-row small { color: #796f7c; }
.toggle { border-color: #aaa398; background: #ebe7dc; }
.toggle:after { background: #817786; }
.toggle.on { background: #74887a; border-color: #5f7467; }
.toggle.on:after { background: #fffdf7; }
.difficulty { background: #f3efe3; border-color: #b8ad98; color: #44384f; }
.briefing-aside { color: #71677a; }
.briefing-aside b { color: #8d6a35; }
.modal-rule { background: linear-gradient(90deg, #ad8548, transparent); }
.save-info { color: #71677a; }
.toast { box-shadow: 0 6px 25px rgba(48,37,63,.18); }
.exit-screen p { color: #62566d; }

@media (max-width: 680px) {
  .hero-vignette { background: linear-gradient(90deg, rgba(246,240,223,.88), rgba(246,240,223,.35)), linear-gradient(0deg,#f6f0df,transparent 45%,#f6f0df); }
}

